  --ooz-pixel: "Silkscreen", ui-monospace, monospace;
  --ooz-lcd: "VT323", ui-monospace, monospace;
  --ooz-drip-font: "Rubik Wet Paint", Impact, fantasy;
  --ooz-band: 56px;          /* room above the page for the dripping bar */
  --ooz-gap: 24px;           /* sidebar-to-page gap the strings cross */
  --ooz-blob-r: 14px 20px 12px 18px / 18px 12px 20px 14px;
}

/* ---------- Neon Vat (dark) is the default ---------- */
:root {
  --ooz-side-a: #2b5000;
  --ooz-side-b: #244400;
  --ooz-text: #f5ffd0;
  --ooz-title: #CCFF00;
  --ooz-tab: #3a6c00;
  --ooz-tab-hover: #447c00;
  --ooz-rim: rgba(204, 255, 0, .5);
  --ooz-sel: #CCFF00;
  --ooz-sel-text: #152400;
  --ooz-sel-rim: #eaff6a;
  --ooz-popup: #1c3800;
  --ooz-panel: rgba(20, 44, 0, .84);
  --ooz-border: rgba(204, 255, 0, .8);
  --ooz-cast: 120, 215, 0;
  --ooz-lcd-bg: #173300;
  --ooz-lcd-text: #CCFF00;
  --ooz-accent: #CCFF00;
  --ooz-accent-2: #ff66ff;
  --ooz-taffy-rim: rgba(204, 255, 0, .7);
  --ooz-drop: #CCFF00;
  --ooz-bar: var(--ooz-bar-dark);
  --ooz-edge: var(--ooz-edge-dark);
}
/* Full Pour (light) when Zen is in light mode */
:root[zen-should-be-dark-mode="false"] {
    --ooz-side-a: #e6ff5c;
    --ooz-side-b: #d6f91a;
    --ooz-text: #152400;
    --ooz-title: #1f3a00;
    --ooz-tab: #f6ffc4;
    --ooz-tab-hover: #fbffe0;
    --ooz-rim: rgba(47, 82, 0, .45);
    --ooz-sel: #2f5200;
    --ooz-sel-text: #eaff6a;
    --ooz-sel-rim: #7ab800;
    --ooz-popup: #f1ffb0;
    --ooz-panel: rgba(246, 255, 196, .88);
    --ooz-border: #7ab800;
    --ooz-cast: 110, 190, 0;
    --ooz-lcd-bg: #2f5200;
    --ooz-lcd-text: #eaff6a;
    --ooz-accent: #7ab800;
    --ooz-accent-2: #b000b0;
    --ooz-taffy-rim: #7ab800;
    --ooz-drop: #86c400;
    --ooz-bar: var(--ooz-bar-light);
    --ooz-edge: var(--ooz-edge-light);
}
