/* ---------- hand the palette to Zen and Firefox ---------- */
:root {
  --zen-primary-color: var(--ooz-accent) !important;
  --zen-colors-primary: var(--ooz-tab) !important;
  --zen-colors-secondary: var(--ooz-tab-hover) !important;
  --zen-colors-tertiary: var(--ooz-side-b) !important;
  --zen-colors-border: var(--ooz-rim) !important;
  --zen-main-browser-background: var(--ooz-side-a) !important;
  --toolbox-textcolor: var(--ooz-text) !important;
  --toolbar-color: var(--ooz-text) !important;
  --toolbar-field-background-color: var(--ooz-lcd-bg) !important;
  --toolbar-field-focus-background-color: var(--ooz-lcd-bg) !important;
  --toolbar-field-color: var(--ooz-lcd-text) !important;
  --toolbar-field-focus-color: var(--ooz-lcd-text) !important;
  /* pop-ups and menus: solid, never see-through */
  --arrowpanel-background: var(--ooz-popup) !important;
  --arrowpanel-color: var(--ooz-text) !important;
  --arrowpanel-border-color: var(--ooz-border) !important;
  --panel-background: var(--ooz-popup) !important;
  --panel-color: var(--ooz-text) !important;
  --panel-border-color: var(--ooz-border) !important;
  --panel-border-radius: 16px !important;
  --arrowpanel-border-radius: 16px !important;
  --menu-background-color: var(--ooz-popup) !important;
  --menu-color: var(--ooz-text) !important;
  --menu-border-color: var(--ooz-border) !important;
  --menuitem-hover-background-color: var(--ooz-lcd-bg) !important;
  --focus-outline-color: var(--ooz-accent) !important;
}

/* ==========================================================================
   Window: deep chartreuse body, the dripping cube bar along the top
   (a background image, so it is always behind the sidebar UI and the page)
   ========================================================================== */
#zen-main-app-wrapper { background: linear-gradient(180deg, var(--ooz-side-a), var(--ooz-side-b)) !important; }
#zen-appcontent-wrapper { position: relative; z-index: 1; }   /* the page sits in front of the goo */
#navigator-toolbox { position: relative; }
@media not (-moz-pref("mod.oozamp.no_bar")) {
  #zen-main-app-wrapper {
    background:
      var(--ooz-bar) -260px 0 / 2000px 124px repeat-x,
      linear-gradient(180deg, var(--ooz-side-a), var(--ooz-side-b)) !important;
  }
  :root:not([zen-compact-mode="true"]) #zen-appcontent-wrapper { margin-top: var(--ooz-band) !important; }
  :root:not([zen-compact-mode="true"]) #navigator-toolbox { padding-top: calc(var(--ooz-band) - 18px) !important; }
}
@media not (-moz-pref("mod.oozamp.no_edge")) {
  :root:not([zen-compact-mode="true"]) #zen-appcontent-wrapper { margin-inline-start: calc(var(--ooz-gap) - var(--zen-element-separation, 8px)) !important; }
  #navigator-toolbox { padding-inline-end: 28px !important; }   /* keeps tabs clear of the goo coat */

/* ---------- sticky-strings edge: coat on the sidebar, strings to the page ---------- */
#navigator-toolbox::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  inset-inline-end: -30px;                      /* 34px on the sidebar, 30px out across the gap */
  width: 64px;
  z-index: 0;
  pointer-events: none;
  background: var(--ooz-edge) 0 -180px / 64px 1600px repeat-y;
  /* the coat always shows; strings fade before the page's rounded corners */
  mask:
    linear-gradient(to right, #000 0 35px, transparent 35px),
    linear-gradient(to bottom, transparent 0 calc(var(--ooz-band) + 26px), #000 calc(var(--ooz-band) + 48px),
                    #000 calc(100% - 44px), transparent calc(100% - 26px));
  mask-composite: add;
}
:root[zen-right-side="true"] #navigator-toolbox::after { transform: scaleX(-1); }
:root[zen-compact-mode="true"] #navigator-toolbox::after { display: none; }
}  /* end: not no_edge */

/* ---------- the page: glowing chartreuse border, green glow under it ---------- */
#tabbrowser-tabbox #tabbrowser-tabpanels .browserSidebarContainer {
  border-radius: var(--ooz-blob-r) !important;
  box-shadow: 0 0 0 1.5px var(--ooz-border), 0 0 22px rgba(204, 255, 0, .22), 0 16px 26px -12px rgba(var(--ooz-cast), .75) !important;
}

/* ==========================================================================
   Sidebar text: the workspace name in dripping letters, LCD address bar
   ========================================================================== */
.zen-current-workspace-indicator-name {
  font-family: var(--ooz-drip-font) !important;
  font-size: 1.35em !important;
  font-weight: 400 !important;
  color: var(--ooz-title) !important;
  letter-spacing: .02em;
}
#urlbar-background {
  background: var(--ooz-lcd-bg) !important;
  border: none !important;
  border-radius: 12px 16px 11px 15px / 15px 11px 16px 12px !important;
  box-shadow: inset 0 0 0 1px rgba(204, 255, 0, .35), 0 0 10px rgba(204, 255, 0, .2) !important;
}
#urlbar:not([breakout-extend]) #urlbar-input {
  font-family: var(--ooz-lcd) !important;
  font-size: 1.32em !important;
  color: var(--ooz-lcd-text) !important;
}
#urlbar[breakout-extend] #urlbar-background { border-radius: 16px !important; }

/* ==========================================================================
   Tabs: blobs of slime stuck together
   ========================================================================== */
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential]) {
  position: relative;
  --ooz-fa: var(--ooz-tab);
  --ooz-fb: var(--ooz-tab);
}
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential]) .tab-background {
  background: var(--ooz-tab) !important;
  border-radius: var(--ooz-r, 16px 22px 14px 20px / 20px 14px 22px 16px) !important;
  box-shadow: inset 0 0 0 1.5px var(--ooz-rim), 0 7px 12px -8px rgba(var(--ooz-cast), .9) !important;
  outline: none !important;
}
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential]):hover .tab-background { background: var(--ooz-tab-hover) !important; }
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential]) .tab-label { color: var(--ooz-text) !important; }
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential])[selected] { --ooz-fa: var(--ooz-sel); }
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential]):has(+ .tabbrowser-tab[selected]) { --ooz-fb: var(--ooz-sel); }
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential])[selected] .tab-background {
  background: var(--ooz-sel) !important;
  box-shadow: inset 0 0 0 1.5px var(--ooz-sel-rim), 0 0 14px rgba(204, 255, 0, .35), 0 9px 14px -7px rgba(var(--ooz-cast), .95) !important;
}
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential])[selected] :is(.tab-label, .tab-close-button) { color: var(--ooz-sel-text) !important; }
#tabbrowser-tabs .tabbrowser-tab .tab-close-button:hover { background: #ff00ff !important; color: #fff !important; border-radius: 50% !important; }
.tabbrowser-tab[soundplaying] .tab-icon-overlay, .tabbrowser-tab .tab-audio-button { color: var(--ooz-accent-2) !important; }

/* irregular shapes, so no two neighbours match */
.tabbrowser-tab:nth-child(5n+1) { --ooz-r: 16px 24px 14px 20px / 22px 14px 24px 16px; }
.tabbrowser-tab:nth-child(5n+2) { --ooz-r: 22px 15px 20px 13px / 15px 22px 13px 20px; }
.tabbrowser-tab:nth-child(5n+3) { --ooz-r: 14px 20px 24px 15px / 18px 24px 14px 20px; }
.tabbrowser-tab:nth-child(5n+4) { --ooz-r: 20px 14px 16px 24px / 14px 20px 24px 16px; }
.tabbrowser-tab:nth-child(5n)   { --ooz-r: 18px 24px 13px 19px / 24px 13px 19px 18px; }

/* goo necks between neighbouring tabs: one still masked shape each */
#tabbrowser-tabs .tabbrowser-tab:not([zen-essential]):has(+ .tabbrowser-tab:not([zen-essential]))::after {
  content: "";
  position: absolute;
  inset-inline: 14px;
  top: calc(100% - 5px);
  height: 16px;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(var(--ooz-fa), var(--ooz-fb));
  mask: var(--ooz-bridge, var(--ooz-b1)) 0 0 / 100% 100% no-repeat;
  transition: opacity .15s ease;
}
.tabbrowser-tab:nth-child(7n+1) { --ooz-bridge: var(--ooz-b1); }
.tabbrowser-tab:nth-child(7n+2) { --ooz-bridge: var(--ooz-b3); }
.tabbrowser-tab:nth-child(7n+3) { --ooz-bridge: var(--ooz-b5); }
.tabbrowser-tab:nth-child(7n+4) { --ooz-bridge: var(--ooz-b2); }
.tabbrowser-tab:nth-child(7n+5) { --ooz-bridge: var(--ooz-b4); }
.tabbrowser-tab:nth-child(7n+6) { --ooz-bridge: var(--ooz-b3); }
.tabbrowser-tab:nth-child(7n+7) { --ooz-bridge: var(--ooz-b1); }
/* while a tab moves, the necks let go; they stick again on drop */
#tabbrowser-tabs[movingtab] .tabbrowser-tab::after { opacity: 0; }
.tabbrowser-tab[ooz-restick]::after { animation: ooz-restick .42s cubic-bezier(.3, 1.6, .5, 1) both; }

/* ---------- one-shot motion (transform only) ---------- */
#tabbrowser-tabs[movingtab] .tabbrowser-tab:is([selected], [multiselected]) .tab-background { animation: ooz-lift .45s cubic-bezier(.3, 1.5, .5, 1); }
.tabbrowser-tab[ooz-recoil] .tab-background { animation: ooz-recoil .55s cubic-bezier(.3, 1.5, .5, 1); }
.tabbrowser-tab[ooz-plop] .tab-background { animation: ooz-plop .5s cubic-bezier(.3, 1.5, .5, 1); }
#tabbrowser-tabs .tabbrowser-tab[fadein]:not([zen-essential]) .tab-background { animation: ooz-blorp .5s cubic-bezier(.3, 1.6, .5, 1) both; }
@keyframes ooz-lift { 35% { transform: scale(1.07, .9); } 65% { transform: scale(.97, 1.06); } }
@keyframes ooz-recoil { 0% { transform: scale(.86, 1.16); } 35% { transform: scale(1.1, .9); } 65% { transform: scale(.97, 1.04); } }
@keyframes ooz-plop { 0% { transform: scale(1.08, .82); } 40% { transform: scale(.95, 1.08); } 70% { transform: scale(1.02, .98); } }
@keyframes ooz-blorp { 0% { transform: scale(.2, .5); opacity: 0; } 55% { transform: scale(1.06, .92); opacity: 1; } }
@keyframes ooz-restick { 0% { transform: scale(.5, 0); opacity: 0; } 60% { transform: scale(1.05, 1.25); opacity: 1; } }

/* ==========================================================================
   Essentials: sewer-pipe mouths; the selected one oozes over its lip
   ========================================================================== */
.tabbrowser-tab[zen-essential] .tab-background {
  border-radius: 14px !important;
  background:
    radial-gradient(circle closest-side, #050604 0 64%, transparent 66%),
    radial-gradient(circle closest-side, rgba(0, 0, 0, .65) 0 72%, transparent 75%),
    radial-gradient(circle closest-side, #a7ae9f 0 83%, #3b3f37 88%, #22251f 93%, transparent 95%),
    var(--ooz-tab) !important;
  box-shadow: inset 0 0 0 1.5px var(--ooz-rim), 0 6px 10px -5px rgba(var(--ooz-cast), .8) !important;
}
.tabbrowser-tab[zen-essential][selected] .tab-background {
  background:
    radial-gradient(ellipse 22% 16% at 50% 82%, #ccff00 0 60%, transparent 64%),
    radial-gradient(circle closest-side, #050604 0 64%, transparent 66%),
    radial-gradient(circle closest-side, rgba(0, 0, 0, .65) 0 72%, transparent 75%),
    radial-gradient(circle closest-side, #a7ae9f 0 83%, #3b3f37 88%, #22251f 93%, transparent 95%),
    var(--ooz-sel) !important;
  box-shadow: 0 0 0 1.5px var(--ooz-sel-rim), 0 0 14px rgba(204, 255, 0, .5) !important;
}
.tabbrowser-tab[zen-essential] .tab-icon-image { filter: drop-shadow(0 0 3px rgba(204, 255, 0, .6)); }

/* ==========================================================================
   Pop-ups and menus: solid, glowing chartreuse border, blobby corners
   ========================================================================== */
menupopup, panel { --panel-padding: 6px; }
menupopup menuitem:not([disabled]):hover, menupopup menu:not([disabled]):hover,
menupopup menuitem[_moz-menuactive]:not([disabled]), menupopup menu[_moz-menuactive]:not([disabled]) {
  color: var(--ooz-lcd-text) !important;
  box-shadow: inset 3px 0 0 #ff00ff;
}
tooltip { background: var(--ooz-popup) !important; color: var(--ooz-text) !important; border: 1.5px solid var(--ooz-border) !important; border-radius: 10px !important; }

/* ==========================================================================
   The taffy drag's own pieces (drawn by ooz-gel.uc.js)
   ========================================================================== */
#ooz-goo-layer .ooz-ghost {
  position: fixed;
  left: 0;
  top: 0;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 11px;
  box-sizing: border-box;
  font: 13px/1 -apple-system, "Segoe UI", system-ui, sans-serif;
  color: var(--ooz-text);
  background: var(--ooz-ghost-fill, var(--ooz-tab));
  border-radius: 16px 22px 14px 20px / 20px 14px 22px 16px;
  box-shadow: inset 0 0 0 1.5px var(--ooz-sel-rim), 0 0 18px rgba(204, 255, 0, .5), 0 16px 22px -8px rgba(var(--ooz-cast), 1);
  will-change: transform;
  white-space: nowrap;
  overflow: hidden;
  transition: opacity .18s ease;
}
#ooz-goo-layer .ooz-ghost[selected] { color: var(--ooz-sel-text); }
#ooz-goo-layer .ooz-ghost img { width: 16px; height: 16px; flex: none; }
#ooz-goo-layer .ooz-ghost span { overflow: hidden; text-overflow: ellipsis; }
#ooz-goo-layer .ooz-ghost.ooz-recoil > * { animation: ooz-recoil .55s cubic-bezier(.3, 1.5, .5, 1); }
#ooz-goo-layer .ooz-skull { position: fixed; left: 0; top: 0; width: 15px; height: 15px; opacity: 0; will-change: transform; }
#ooz-goo-layer .ooz-drop { position: fixed; width: 0; height: 0; transition: opacity .5s ease; }
#ooz-goo-layer .ooz-drop > div { position: absolute; left: 0; top: 0; transform-origin: 0 10px; animation: ooz-fall .75s cubic-bezier(.5, 0, .9, .6) forwards; }
#ooz-goo-layer .ooz-drop svg { position: absolute; left: -10px; top: -8px; width: 20px; height: 26px; overflow: visible; }
#ooz-goo-layer .ooz-drop.big svg { left: -16px; top: -14px; width: 32px; height: 42px; }
#ooz-goo-layer .ooz-drop.big img { position: absolute; left: -8px; top: 3px; width: 16px; height: 16px; opacity: .92; }
#ooz-goo-layer .ooz-drop.big > div { animation-name: ooz-fallbig; animation-duration: .8s; }
@keyframes ooz-fall { 0% { transform: translateY(0) scale(.5, 1.5); } 70% { transform: translateY(var(--fall)) scale(.85, 1.2); } 80% { transform: translateY(var(--fall)) scale(1.7, .45); } 100% { transform: translateY(var(--fall)) scale(1.4, .6); } }
@keyframes ooz-fallbig { 0% { transform: translateY(0) scale(.8, 1.2); } 72% { transform: translateY(var(--fall)) scale(.95, 1.08); } 84% { transform: translateY(var(--fall)) scale(1.18, .84); } 100% { transform: translateY(var(--fall)) scale(1.08, .92); } }

/* ==========================================================================
   Settings (Sine / Zen mod preferences): switch any piece off
   ========================================================================== */
@media (-moz-pref("mod.oozamp.no_bridges")) {
  #tabbrowser-tabs .tabbrowser-tab::after { display: none !important; }
}
@media (-moz-pref("mod.oozamp.plain_url")) {
  #urlbar:not([breakout-extend]) #urlbar-input { font-family: inherit !important; font-size: inherit !important; }
}
@media (-moz-pref("mod.oozamp.plain_workspace_name")) {
  .zen-current-workspace-indicator-name { font-family: inherit !important; font-size: inherit !important; }
}
@media (prefers-reduced-motion: reduce) {
  .tabbrowser-tab .tab-background, .tabbrowser-tab::after, #ooz-goo-layer * { animation: none !important; transition: none !important; }
}
